const endpoints = [
  { id: 'common', name: 'Common Server', host: 'lexi-solution.com', url: 'https://fms.n8n.lexisolution.com/webhook/fms-common-dashboard' },
  { id: 'malaysia', name: 'Malaysia Server', host: 'masterbom.com', url: 'https://fms.n8n.lexisolution.com/webhook/fms-malaysia-dashboard' },
  { id: 'motion', name: 'Motion Server', host: 'master-bom.com', url: 'https://fms.n8n.lexisolution.com/webhook/fms-motion-dashboard' },
  { id: 'volvo', name: 'Volvo Server', host: 'volvo.master-bom.com', url: 'https://fms.n8n.lexisolution.com/webhook/fms-volvo-dashboard' },
  { id: 'hitachi', name: 'Hitachi Server', host: 'hitachi.master-bom.com', url: 'https://fms.n8n.lexisolution.com/webhook/fms-live-dashboard' },
  { id: 'kiekert', name: 'Kiekert Server', host: 'kiekert.master-bom.com', url: 'https://fms.n8n.lexisolution.com/webhook/fms-kiekert-dashboard' },
  { id: 'demo', name: 'Demo Server', host: 'demo.master-bom.com', url: 'https://fms.n8n.lexisolution.com/webhook/fms-demo-dashboard' }
];

return endpoints.map(e => ({ json: e }));

const items = $input.all();
const results = {};
let totalOnline = 0;
let totalSessions = 0;
let allUsers = [];
let allDatabases = [];

for (const item of items) {
  const data = item.json;
  const serverId = item.json.id || 'unknown';
  if (data && data.metrics) {
    totalOnline++;
    totalSessions += parseInt(data.metrics.sessions || 0, 10);
    results[serverId] = data;
    if (data.connectedUsers) {
      allUsers.push(...data.connectedUsers);
    }
    if (data.databases) {
      allDatabases.push(...data.databases);
    }
  } else {
    results[serverId] = { status: 'OFFLINE' };
  }
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    fleetOverview: {
      onlineCount: totalOnline,
      totalServers: items.length,
      totalActiveSessions: totalSessions
    },
    servers: results,
    connectedUsers: allUsers,
    databases: allDatabases
  }
}];
